#!/usr/bin/env node
/**
 * Sitemap validation for Google Search.
 * Usage: node scripts/verify-sitemap.mjs <baseUrl> [--live=live-sitemap.xml] [--snapshot=seo-snapshot.json]
 *
 * Checks the sitemap generated by the app: XML shape, limits, URL format, duplicates,
 * no redirect sources inside, canonical and hreflang pairs (when a snapshot is given).
 * With --live compares to the sitemap that is currently indexed: every URL that left the map
 * must answer with a permanent redirect to a URL that stays in the map.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const args = process.argv.slice(2);
const base = (args.find((a) => /^https?:/.test(a)) || 'http://localhost:3111').replace(/\/$/, '');
const opt = (name) => (args.find((a) => a.startsWith(`--${name}=`)) || '').slice(name.length + 3);
const livePath = opt('live');
const snapPath = opt('snapshot');

const HOST = 'https://meddera.md';
const errors = [];
const warn = [];
const fail = (m) => errors.push(m);

const norm = (u) => u.replace(/^https?:\/\/[^/]+/, '').replace(/\/$/, '') || '/';

function parse(xml, label) {
  if (!xml.startsWith('<?xml version="1.0" encoding="UTF-8"?>')) fail(`${label}: no XML declaration`);
  if (!/<urlset[^>]+xmlns="http:\/\/www\.sitemaps\.org\/schemas\/sitemap\/0\.9"/.test(xml)) fail(`${label}: urlset namespace is missing`);
  if (!/<\/urlset>\s*$/.test(xml)) fail(`${label}: urlset is not closed`);
  const blocks = [...xml.matchAll(/<url>([\s\S]*?)<\/url>/g)].map((m) => m[1]);
  const opens = (xml.match(/<url>/g) || []).length;
  if (opens !== blocks.length) fail(`${label}: unbalanced <url> tags (${opens} open, ${blocks.length} closed)`);
  return blocks.map((b) => ({
    loc: (b.match(/<loc>([^<]*)<\/loc>/) || [])[1] || '',
    lastmod: (b.match(/<lastmod>([^<]*)<\/lastmod>/) || [])[1] || '',
    changefreq: (b.match(/<changefreq>([^<]*)<\/changefreq>/) || [])[1] || '',
    priority: (b.match(/<priority>([^<]*)<\/priority>/) || [])[1] || '',
  }));
}

// ---------- local sitemap ----------
const res = await fetch(`${base}/sitemap.xml`);
if (res.status !== 200) {
  console.error(`sitemap.xml answers ${res.status}`);
  process.exit(1);
}
const ctype = res.headers.get('content-type') || '';
if (!/xml/.test(ctype)) fail(`content-type is "${ctype}", expected xml`);
const xml = await res.text();
const entries = parse(xml, 'local');
if (entries.length > 50000) fail(`more than 50000 URLs: ${entries.length}`);
if (Buffer.byteLength(xml) > 50 * 1024 * 1024) fail('sitemap is larger than 50 MB');

const seen = new Set();
const today = new Date().toISOString().slice(0, 10);
const FREQ = new Set(['always', 'hourly', 'daily', 'weekly', 'monthly', 'yearly', 'never']);
let withLastmod = 0;
for (const e of entries) {
  if (!e.loc) { fail('entry without <loc>'); continue; }
  if (!e.loc.startsWith(`${HOST}/`) && e.loc !== HOST) fail(`${e.loc}: wrong host`);
  if (/[?#\s]/.test(e.loc)) fail(`${e.loc}: query, fragment or whitespace in URL`);
  if (!/^[\x21-\x7e]+$/.test(e.loc)) fail(`${e.loc}: non-ASCII or control characters (must be percent-encoded)`);
  if (/&(?!amp;)/.test(e.loc)) fail(`${e.loc}: unescaped ampersand`);
  if (e.loc.length > 2048) fail(`${e.loc}: longer than 2048 characters`);
  const key = norm(e.loc);
  if (seen.has(key)) fail(`${e.loc}: duplicate`);
  seen.add(key);
  if (e.lastmod) {
    withLastmod++;
    if (!/^\d{4}-\d{2}-\d{2}(T[\d:.]+(Z|[+-]\d{2}:\d{2}))?$/.test(e.lastmod) || Number.isNaN(Date.parse(e.lastmod))) fail(`${e.loc}: bad lastmod "${e.lastmod}"`);
    else if (e.lastmod.slice(0, 10) > today) fail(`${e.loc}: lastmod in the future ${e.lastmod}`);
  }
  if (e.changefreq && !FREQ.has(e.changefreq)) fail(`${e.loc}: bad changefreq "${e.changefreq}"`);
  if (e.priority) {
    const p = Number(e.priority);
    if (!(p >= 0 && p <= 1)) fail(`${e.loc}: priority out of 0..1`);
  }
}

// every lastmod that is set must not be today's build date for pages without real edits
const buildStamped = entries.filter((e) => e.lastmod === today && !/\/blog/.test(e.loc));
if (buildStamped.length) fail(`${buildStamped.length} non-blog URL(s) carry today's date as lastmod (build time, not a real edit): ${buildStamped[0].loc}`);

// ---------- redirect sources ----------
const redirectsFile = path.join(here, '../src/blog-data/blog-redirects.json');
const rows = JSON.parse(fs.readFileSync(redirectsFile, 'utf8'));
const redirectMap = new Map();
for (const r of rows) {
  redirectMap.set(`/blog/${r.ruSlug}`, r.ruTo);
  redirectMap.set(`/ro/blog/${r.roSlug}`, r.roTo);
}
for (const e of entries) {
  const p = norm(e.loc);
  if (redirectMap.has(p)) fail(`${e.loc}: is a redirect source but listed in the sitemap`);
}
for (const [from, to] of redirectMap) {
  if (!seen.has(to)) fail(`redirect ${from} -> ${to}: target is not in the sitemap`);
}

// ---------- canonical and hreflang (snapshot) ----------
if (snapPath) {
  const snap = JSON.parse(fs.readFileSync(snapPath, 'utf8'));
  let checked = 0;
  for (const e of entries) {
    const p = norm(e.loc);
    const s = snap[p] || snap[p + '/'];
    if (!s) { warn.push(`no snapshot for ${p}`); continue; }
    checked++;
    if (s.robots && /noindex/i.test(String(s.robots))) fail(`${p}: noindex but listed in the sitemap`);
    if (!s.canonical) fail(`${p}: no canonical`);
    else if (norm(s.canonical) !== p) fail(`${p}: canonical is ${s.canonical}`);
    const alt = s.alternates || {};
    if (!alt.ru || !alt.ro) fail(`${p}: hreflang ru/ro pair is incomplete`);
    else {
      for (const k of ['ru', 'ro']) if (!seen.has(norm(alt[k]))) fail(`${p}: hreflang ${k} ${alt[k]} is not in the sitemap`);
      if (alt.ru && alt.ro && norm(alt.ru) === norm(alt.ro)) fail(`${p}: hreflang ru and ro are the same URL`);
    }
  }
  console.log(`snapshot: canonical and hreflang checked for ${checked} URLs`);
}

// ---------- live sitemap ----------
let liveInfo = '';
if (livePath) {
  const live = parse(fs.readFileSync(livePath, 'utf8'), 'live');
  const liveSet = new Set(live.map((e) => norm(e.loc)));
  const kept = [...liveSet].filter((p) => seen.has(p));
  const gone = [...liveSet].filter((p) => !seen.has(p));
  const added = [...seen].filter((p) => !liveSet.has(p));
  const covered = gone.filter((p) => redirectMap.has(p));
  const rest = gone.filter((p) => !redirectMap.has(p));

  const queue = [...rest];
  const viaRoute = [];
  async function probe(p) {
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        const r = await fetch(base + p, { redirect: 'manual' });
        const loc = r.headers.get('location') || '';
        if (![301, 308].includes(r.status)) return fail(`live URL ${p} left the sitemap and answers ${r.status} instead of a permanent redirect`);
        const target = norm(loc);
        if (!seen.has(target)) return fail(`live URL ${p} redirects to ${loc}, which is not in the new sitemap`);
        viaRoute.push([p, target]);
        return;
      } catch (e) {
        if (attempt === 2) fail(`live URL ${p}: ${e.message}`);
      }
    }
  }
  await Promise.all(Array.from({ length: 4 }, async () => { while (queue.length) await probe(queue.shift()); }));

  const byTarget = {};
  for (const [, t] of viaRoute) byTarget[t] = (byTarget[t] || 0) + 1;
  liveInfo = [
    `live sitemap: ${liveSet.size} URLs`,
    `  stay in the map unchanged: ${kept.length}`,
    `  left the map, covered by article redirects: ${covered.length}`,
    `  left the map, covered by route redirect: ${viaRoute.length} ${JSON.stringify(byTarget)}`,
    `  new in the map: ${added.length}`,
  ].join('\n');
  if (added.length) fs.writeFileSync(path.join(process.env.TMPDIR || '/tmp', 'sitemap-new-urls.txt'), added.join('\n') + '\n');
}

console.log(`local sitemap: ${entries.length} URLs, ${withLastmod} with lastmod, ${entries.length - withLastmod} without`);
if (liveInfo) console.log(liveInfo);
if (warn.length) console.log(`warnings: ${warn.length}\n${warn.slice(0, 10).join('\n')}`);
if (errors.length) {
  console.error(errors.slice(0, 60).join('\n'));
  console.error(`\nverify-sitemap: ${errors.length} problem(s)`);
  process.exit(1);
}
console.log('verify-sitemap: OK');
